import React, { useCallback, useEffect } from 'react';

import { useMultiMeterBarTooltipState } from './store/selectors.js';
import { useTooltip } from './useTooltip.js';

//TODO ADES-4964 move to core folder and reuse across charts
export const useTooltipEventListeners = (
  tooltipRef: React.RefObject<HTMLDivElement>,
) => {
  const { pinned } = useMultiMeterBarTooltipState();
  const { hideTooltip } = useTooltip();

  const onEscapeKeyPressedHandler = useCallback(
    (event: KeyboardEvent) => {
      if (pinned && event.key === 'Escape') {
        hideTooltip();
      }
    },
    [hideTooltip, pinned],
  );

  const onClickOutsideChartHandler = useCallback(
    (event: MouseEvent) => {
      if (pinned && !tooltipRef.current?.contains(event.target as Node)) {
        hideTooltip();
      }
    },
    [hideTooltip, pinned, tooltipRef],
  );

  useEffect(() => {
    window.addEventListener('keyup', onEscapeKeyPressedHandler);
    window.addEventListener('click', onClickOutsideChartHandler);

    return () => {
      window.removeEventListener('keyup', onEscapeKeyPressedHandler);
      window.removeEventListener('click', onClickOutsideChartHandler);
    };
  }, [onEscapeKeyPressedHandler, onClickOutsideChartHandler]);

  return {
    onEscapeKeyPressedHandler,
  };
};
